// ─── Produk Komersial Obat — Brand & Produk Registry ─────────────────────────
// PKO-002: Database PRODUK DAGANG obat komersial (bukan database referensi
// seperti Master Obat). Struktur: Brand → Produk, mengikuti pola Produk
// Komersial Pakan (lihat produkKomersialData.ts / konsentratMerekData.ts).
//
// PKO-003: Katalog 10 Brand dan 160 Produk. PCR-002: Setiap produk dilengkapi Setiap Produk memiliki
// masterObatUuid WAJIB yang merujuk ke obatData.ts (Master Obat) —
// relasi produk dagang → obat generik. Field pengayaan: bahanAktif, kekuatan, negaraAsal, penyimpanan.
// PKO-004: CRUD Brand/Produk via Admin (Kelola Brand, Kelola Produk).
// PKO-006: Detail Produk read-only dengan referensi Master Obat.
// PKO-007: Import/Export JSON+CSV dengan validasi relasi penuh.
// Belum termasuk: Harga, Supplier, Batch, Expired, Stok, Marketplace.
//
// PK-000A: Setiap Brand dan Produk memiliki UUID v4 permanen sebagai identitas
// utama. UUID TIDAK ditampilkan pada UI. Relasi Produk → Brand menggunakan
// brandId (UUID), relasi Produk → Master Obat menggunakan masterObatUuid
// (UUID, merujuk ke ObatItem.uuid di obatData.ts).

// ─── UUID Registry — Brand ────────────────────────────────────────────────────
