/** Lookup produk UUID dari slug. Digunakan untuk membangun relasi data. */
export function getObatProdukUUID(slug: string): string {
  const id = OBAT_PRODUK_UUID[slug];
  if (!id) {
    console.error(`[PK-000A] Produk obat slug "${slug}" tidak memiliki UUID terdaftar.`);
    throw new Error(`Unknown produk slug: ${slug}`);
  }
  return id;
}

// ─── Tipe Entitas ─────────────────────────────────────────────────────────────

export type StatusProdukObat = 'aktif' | 'nonaktif';

export interface ObatBrand {
  /** UUID v4 — identitas permanen brand (PK-000A). Tidak ditampilkan di UI. */
  uuid: string;
  /** Slug — HANYA untuk routing/navigasi UI, bukan primary key. */
  slug: string;
  nama: string;
  logo: string; // Emoji/URL placeholder selama belum ada aset logo nyata; opsional secara fungsional
  /** Opsional. PKO-004: ditambahkan untuk Admin Kelola Brand. */
  deskripsi?: string;
  jumlahProduk: number;
  status: StatusProdukObat;
  color: string;
  bg: string;
}

export interface ObatProdukKomersial {
  /** UUID v4 — identitas permanen produk (PK-000A). Tidak ditampilkan di UI. */
  uuid: string;
  /** Slug — HANYA untuk routing/navigasi UI, bukan primary key. */
  slug: string;
  nama: string;
  /** Relasi ke ObatBrand.uuid — bukan nama/slug brand. */
  brandId: string;
  brandNama: string; // denormalized untuk tampilan cepat
  bentukSediaan: string;
  kemasan: string;
  status: StatusProdukObat;
  /**
   * Relasi WAJIB ke Master Obat (ObatItem.uuid di obatData.ts). Produk
   * Komersial adalah produk dagang dari suatu obat generik referensi —
   * setiap entri harus menunjuk ke referensi generiknya.
   */
  masterObatUuid: string;
  // ── PKO-004: Field Admin (opsional pada katalog dummy lama; wajib diisi
  // melalui form Admin untuk entri baru — lihat validasi di
  // produkKomersialObatAdminValidation.ts) ──────────────────────────────────
  /** Nama komersial/dagang yang tampil di kemasan (bisa berbeda dari `nama` internal). */
  namaKomersial?: string;
  produsen?: string;
  distributor?: string;
  nomorRegistrasi?: string;
  fotoProduk?: string;
  catatan?: string;
  // ── PCR-002: Enrichment Fields ────────────────────────────────────────────
  /** Bahan aktif/active ingredient sesuai label kemasan produk. */
  bahanAktif?: string;
  /** Kekuatan/kadar bahan aktif per unit sediaan (misal: "200 mg/mL", "10%"). */
  kekuatan?: string;
  /** Negara asal produsen (misal: "Indonesia", "Prancis", "Amerika Serikat"). */
  negaraAsal?: string;
  /** Kondisi penyimpanan sesuai rekomendasi label produk. */
  penyimpanan?: string;
}

