// ─── Helpers (live-computed dari data di atas) ────────────────────────────────

export function getTotalBrandObat(): number {
  return OBAT_BRAND_LIST.length;
}

export function getTotalProdukObat(): number {
  return OBAT_PRODUK_LIST.length;
}

export function getTotalProdukAktifObat(): number {
  return OBAT_PRODUK_LIST.filter((p) => p.status === 'aktif').length;
}

export function getTotalProdukNonaktifObat(): number {
  return OBAT_PRODUK_LIST.filter((p) => p.status === 'nonaktif').length;
}

export function getObatProdukByBrandId(brandId: string): ObatProdukKomersial[] {
  return OBAT_PRODUK_LIST.filter((p) => p.brandId === brandId);
}

// ═══════════════════════════════════════════════════════════════════════════
// PKO-004 — Admin Produk Komersial Obat: CRUD & Soft Delete
// ═══════════════════════════════════════════════════════════════════════════
// Kelola Brand dan Kelola Produk. Master Obat (obatData.ts) tetap menjadi
// Single Source of Truth — modul ini hanya menyimpan relasi (masterObatUuid)
// ke referensi tersebut, tidak pernah menyalin/mengubah datanya.

/** jumlahProduk selalu diproyeksikan langsung dari OBAT_PRODUK_LIST agar tidak pernah drift. */
function withLiveJumlahProdukObat(brand: ObatBrand): ObatBrand {
  const jumlahProduk = OBAT_PRODUK_LIST.filter((p) => p.brandId === brand.uuid).length;
  return jumlahProduk === brand.jumlahProduk ? brand : { ...brand, jumlahProduk };
}

/** Daftar Brand dengan jumlahProduk live — gunakan ini (bukan OBAT_BRAND_LIST mentah) di UI. */
export function getObatBrandListLive(): ObatBrand[] {
  return OBAT_BRAND_LIST.map(withLiveJumlahProdukObat);
}

export function getObatBrandByUuid(uuid: string): ObatBrand | undefined {
  const found = OBAT_BRAND_LIST.find((b) => b.uuid === uuid);
  return found ? withLiveJumlahProdukObat(found) : undefined;
}

export function getObatProdukKomersialByUuid(uuid: string): ObatProdukKomersial | undefined {
  return OBAT_PRODUK_LIST.find((p) => p.uuid === uuid);
}

/** PKO-006: Lookup produk komersial obat dari slug — dipakai untuk routing Detail Produk. */
export function getObatProdukBySlug(slug: string): ObatProdukKomersial | undefined {
  return OBAT_PRODUK_LIST.find((p) => p.slug === slug);
}

/** Slugify sederhana untuk entri baru yang dibuat via Admin (bukan primary key, hanya untuk routing). */
function slugifyObat(nama: string, uuid: string): string {
  const base = nama.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
  return base ? `${base}-${uuid.slice(0, 8)}` : uuid;
}

const OBAT_BRAND_PALETTE: { color: string; bg: string }[] = [
  { color: '#0d6efd', bg: '#e7f1ff' }, { color: '#1b7a43', bg: '#e8f5ee' },
  { color: '#6a1b9a', bg: '#f3e5f5' }, { color: '#b8860b', bg: '#fbf1dd' },
  { color: '#c0392b', bg: '#fbeaea' }, { color: '#117864', bg: '#e1f5f0' },
];

export interface ObatAdminMutationResult {
  ok: boolean;
  error?: string;
}

/** Case-insensitive duplicate check nama Brand, mengecualikan satu UUID (untuk edit). */
export function isDuplicateObatBrandNama(nama: string, excludeUuid?: string): boolean {
  const target = nama.trim().toLowerCase();
  return OBAT_BRAND_LIST.some((b) => b.uuid !== excludeUuid && b.nama.trim().toLowerCase() === target);
}

/** Case-insensitive duplicate check nama Produk dalam Brand yang sama, mengecualikan satu UUID (untuk edit). */
export function isDuplicateObatProdukNama(brandId: string, nama: string, excludeUuid?: string): boolean {
  const target = nama.trim().toLowerCase();
  return OBAT_PRODUK_LIST.some((p) =>
    p.uuid !== excludeUuid && p.brandId === brandId && p.nama.trim().toLowerCase() === target
  );
}

export function addObatBrand(input: { nama: string; logo: string; deskripsi: string }): ObatBrand {
  const uuid = crypto.randomUUID();
  const palette = OBAT_BRAND_PALETTE[OBAT_BRAND_LIST.length % OBAT_BRAND_PALETTE.length];
  const brand: ObatBrand = {
    uuid,
    slug: slugifyObat(input.nama, uuid),
    nama: input.nama.trim(),
    logo: input.logo.trim() || '💊',
    deskripsi: input.deskripsi.trim(),
    jumlahProduk: 0,
    status: 'aktif',
    color: palette.color,
    bg: palette.bg,
  };
  OBAT_BRAND_LIST.push(brand);
  return brand;
}

export function updateObatBrand(uuid: string, updates: {
  nama?: string; logo?: string; deskripsi?: string; status?: StatusProdukObat;
}): ObatBrand | undefined {
  const brand = OBAT_BRAND_LIST.find((b) => b.uuid === uuid);
  if (!brand) return undefined;
  if (updates.nama !== undefined) brand.nama = updates.nama.trim();
  if (updates.logo !== undefined) brand.logo = updates.logo.trim() || '💊';
  if (updates.deskripsi !== undefined) brand.deskripsi = updates.deskripsi.trim();
  if (updates.status !== undefined) {
    brand.status = updates.status;
    // Denormalized brand name on child products must stay in sync.
    OBAT_PRODUK_LIST.forEach((p) => { if (p.brandId === uuid) p.brandNama = brand.nama; });
  } else if (updates.nama !== undefined) {
    OBAT_PRODUK_LIST.forEach((p) => { if (p.brandId === uuid) p.brandNama = brand.nama; });
  }
  return brand;
}

/** Brand tidak boleh dinonaktifkan apabila masih memiliki Produk aktif. */
export function canDeactivateObatBrand(uuid: string): ObatAdminMutationResult {
  const brand = OBAT_BRAND_LIST.find((b) => b.uuid === uuid);
  if (!brand) return { ok: false, error: 'Data referensi tidak valid.' };
  const hasActiveChild = OBAT_PRODUK_LIST.some((p) => p.brandId === uuid && p.status === 'aktif');
  if (hasActiveChild) return { ok: false, error: 'Brand masih memiliki Produk aktif. Nonaktifkan produk terlebih dahulu.' };
  return { ok: true };
}

/** Soft delete — status menjadi 'nonaktif'. UUID dan data tidak pernah dihapus. */
export function softDeleteObatBrand(uuid: string): ObatAdminMutationResult {
  const check = canDeactivateObatBrand(uuid);
  if (!check.ok) return check;
  updateObatBrand(uuid, { status: 'nonaktif' });
  return { ok: true };
}

export function restoreObatBrand(uuid: string): void {
  updateObatBrand(uuid, { status: 'aktif' });
}

export function addObatProdukKomersial(input: {
  brandId: string; masterObatUuid: string; nama: string; namaKomersial: string;
  bentukSediaan: string; kemasan: string; produsen: string;
  distributor?: string; nomorRegistrasi?: string; fotoProduk?: string; catatan?: string;
}): ObatProdukKomersial {
  const brand = OBAT_BRAND_LIST.find((b) => b.uuid === input.brandId);
  if (!brand) throw new Error('Data referensi tidak valid: brand tidak ditemukan.');
  const uuid = crypto.randomUUID();
  const produk: ObatProdukKomersial = {
    uuid,
    slug: slugifyObat(input.nama, uuid),
    nama: input.nama.trim(),
    brandId: input.brandId,
    brandNama: brand.nama,
    bentukSediaan: input.bentukSediaan.trim(),
    kemasan: input.kemasan.trim(),
    status: 'aktif',
    masterObatUuid: input.masterObatUuid,
    namaKomersial: input.namaKomersial.trim(),
    produsen: input.produsen.trim(),
    distributor: input.distributor?.trim() || undefined,
    nomorRegistrasi: input.nomorRegistrasi?.trim() || undefined,
    fotoProduk: input.fotoProduk?.trim() || undefined,
    catatan: input.catatan?.trim() || undefined,
  };
  OBAT_PRODUK_LIST.push(produk);
  return produk;
}

export function updateObatProdukKomersial(uuid: string, updates: {
  brandId?: string; masterObatUuid?: string; nama?: string; namaKomersial?: string;
  bentukSediaan?: string; kemasan?: string; produsen?: string;
  distributor?: string; nomorRegistrasi?: string; fotoProduk?: string; catatan?: string;
  status?: StatusProdukObat;
}): ObatProdukKomersial | undefined {
  const produk = OBAT_PRODUK_LIST.find((p) => p.uuid === uuid);
  if (!produk) return undefined;
  if (updates.brandId !== undefined) {
    const brand = OBAT_BRAND_LIST.find((b) => b.uuid === updates.brandId);
    if (!brand) throw new Error('Data referensi tidak valid: brand tidak ditemukan.');
    produk.brandId = updates.brandId;
    produk.brandNama = brand.nama;
  }
  if (updates.masterObatUuid !== undefined) produk.masterObatUuid = updates.masterObatUuid;
  if (updates.nama !== undefined) produk.nama = updates.nama.trim();
  if (updates.namaKomersial !== undefined) produk.namaKomersial = updates.namaKomersial.trim();
  if (updates.bentukSediaan !== undefined) produk.bentukSediaan = updates.bentukSediaan.trim();
  if (updates.kemasan !== undefined) produk.kemasan = updates.kemasan.trim();
  if (updates.produsen !== undefined) produk.produsen = updates.produsen.trim();
  if (updates.distributor !== undefined) produk.distributor = updates.distributor.trim() || undefined;
  if (updates.nomorRegistrasi !== undefined) produk.nomorRegistrasi = updates.nomorRegistrasi.trim() || undefined;
  if (updates.fotoProduk !== undefined) produk.fotoProduk = updates.fotoProduk.trim() || undefined;
  if (updates.catatan !== undefined) produk.catatan = updates.catatan.trim() || undefined;
  if (updates.status !== undefined) produk.status = updates.status;
  return produk;
}

/** Produk adalah leaf entity — tidak ada anak yang perlu dijaga, selalu boleh dinonaktifkan. */
export function softDeleteObatProdukKomersial(uuid: string): ObatAdminMutationResult {
  const produk = OBAT_PRODUK_LIST.find((p) => p.uuid === uuid);
  if (!produk) return { ok: false, error: 'Data referensi tidak valid.' };
  updateObatProdukKomersial(uuid, { status: 'nonaktif' });
  return { ok: true };
}

export function restoreObatProdukKomersial(uuid: string): void {
  updateObatProdukKomersial(uuid, { status: 'aktif' });
}
